/**
 * MT: Hungarian (`hu`), status `complete` per SPD's own convention (`languages.ts` - SPD
 * itself ships Hungarian as reviewed, but that status covers SPD's own `.properties` catalog,
 * not this port-only draft). Machine-translated draft, not a native speaker's pass: adapted
 * key-by-key from `PORT_STRINGS_EN`, every `{placeholder}` token preserved exactly (checked
 * programmatically - see this project's own translation-strategy note in ROADMAP.md
 * section 8), Hungarian grammar/word order applied (informal te-form address), but not
 * proofread by a fluent speaker. Flag this status honestly rather than silently upgrading it
 * to `complete` - matches SPD's own complete/unreviewed/unfinished distinction, which exists
 * precisely so a machine-drafted locale is never confused with a reviewed one.
 */

