	'port.buff.recallused.desc': 'Klerik nedávno použil předmět, který lze použít k seslání kouzla Obnovení runy. Klerik může toto kouzlo použít pro zopakování jeho účinku.\\n\\nPoužitý předmět: {0}.\\n\\nZbývá tahů: {1}.',
